def pods_available(replicas, max_unavailable, terminating, not_ready):
    """How many pods are actually serving, and whether we may kill another."""
    floor = replicas - max_unavailable
    serving = replicas - terminating - not_ready
    may_terminate = serving >= floor
    return {
        "serving": serving,
        "floor": floor,
        "may_terminate": may_terminate,
    }

def ready_for_traffic(pod):
    """Should this pod be in the Service endpoints right now?"""
    return pod["phase"] == "Running"

